def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Tally match statistics.
    my_c = 0
    op_c = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for mine, opp in history:
        if mine == 'C':
            my_c += 1
        if opp == 'C':
            op_c += 1
        if mine == 'C':
            if opp == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if opp == 'C':
                dc += 1
            else:
                dd += 1

    op_d = n - op_c
    op_coop_rate = op_c / n

    # Last opponent moves (up to 6).
    last_opp = history[-1][1]

    # Consecutive opponent defections at the end.
    consec_def = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_def += 1
        else:
            break

    # Consecutive opponent cooperations at the end.
    consec_coop = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            consec_coop += 1
        else:
            break

    # Recent cooperation in a short window.
    w = history[-6:] if n >= 6 else history
    recent_op_c = 0
    for a, b in w:
        if b == 'C':
            recent_op_c += 1
    recent_rate = recent_op_c / len(w)

    # Opening: cooperate, but tolerate a single probe gracefully.
    if n < 4:
        return 'C'

    # Sustained defection: cut losses, with rare probe.
    if op_coop_rate <= 0.12 and n >= 6:
        if n % 23 == 0:
            return 'C'
        return 'D'

    # Opponent nearly always defecting right now: don't feed them.
    if consec_def >= 6:
        if n % 19 == 0:
            return 'C'
        return 'D'

    # All-defect opponent detected early.
    if op_d >= n - 1 and n >= 8:
        if n % 17 == 0:
            return 'C'
        return 'D'

    # Highly cooperative opponent: cooperate, probe sparingly for DC payoff.
    if op_coop_rate >= 0.88 and n >= 12:
        if consec_coop >= 8 and n % 13 == 0:
            return 'D'
        return 'C'

    # Mostly cooperative opponent with an isolated defection: retaliate once
    # then return to cooperation to avoid a long DD spiral.
    if op_coop_rate >= 0.6 and last_opp == 'D':
        if consec_def == 1 and recent_op_c >= 3:
            return 'D'
        # Avoid partner unraveling: return to cooperation quickly.
        if consec_def >= 2:
            return 'C'
        return 'C'

    # Very cooperative overall: keep cooperating.
    if op_coop_rate >= 0.75:
        return 'C'

    # Tit-for-tat response for moderate behavior, with forgiveness.
    if last_opp == 'D':
        if consec_def == 1:
            # One-off defection: retaliate but plan to forgive.
            return 'D'
        if consec_def == 2:
            # Two in a row: punish, then get ready to forgive.
            return 'D'
        # Three or more: forgive occasionally to break the spiral.
        if consec_def >= 3:
            if rng.random() < 0.4 or op_coop_rate >= 0.45:
                return 'C'
            return 'D'
    else:
        # Opponent cooperated last: cooperate back, unless clearly exploitative.
        if op_coop_rate >= 0.4:
            return 'C'
        # Opponent is likely testing; retaliate a bit to signal.
        if op_d * 3 >= n * 2:
            return 'D'
        return 'C'

    # Default: cooperate unless opponent is fairly defection-heavy.
    if op_coop_rate >= 0.35:
        return 'C'
    return 'D'
